TARGETS = list(FILES)
originals: dict[str, bytes | None] = {}


def run(
    command: list[str],
    *,
    check: bool = True,
) -> subprocess.CompletedProcess:
    print("$ " + " ".join(command))
    return subprocess.run(
        command,
        cwd=ROOT,
        check=check,
    )


def is_tracked(relative: str) -> bool:
    return subprocess.run(
        [
            "git",
            "ls-files",
            "--error-unmatch",
            relative,
        ],
        cwd=ROOT,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
    ).returncode == 0


def ensure_safe() -> None:
    changed: list[str] = []

    for relative in TARGETS:
        path = ROOT / relative
        worktree = subprocess.run(
            ["git", "diff", "--quiet", "--", relative],
            cwd=ROOT,
        )
        staged = subprocess.run(
            ["git", "diff", "--cached", "--quiet", "--", relative],
            cwd=ROOT,
        )

        if worktree.returncode or staged.returncode:
            changed.append(relative)
        elif path.exists() and not is_tracked(relative):
            changed.append(relative)

    if changed:
        raise RuntimeError(
            "These target files contain local changes and "
            "were not overwritten:\n"
            + "\n".join(changed)
        )


def preserve(relative: str) -> None:
    if relative in originals:
        return

    path = ROOT / relative
    originals[relative] = (
        path.read_bytes()
        if path.exists()
        else None
    )

    if path.exists():
        backup = BACKUP / relative
        backup.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        shutil.copy2(path, backup)


def install_files() -> None:
    for relative, content in FILES.items():
        preserve(relative)
        path = ROOT / relative
        path.parent.mkdir(
            parents=True,
            exist_ok=True,
        )
        path.write_text(
            textwrap.dedent(content).strip()
            + "\n",
            encoding="utf-8",
        )

        if path.name.startswith("QPX_"):
            path.chmod(0o700)

        print(f"Installed: {relative}")


def restore() -> None:
    print("Restoring previous target files...")

    for relative, original in originals.items():
        path = ROOT / relative

        if original is None:
            if path.exists():
                path.unlink()
        else:
            path.parent.mkdir(
                parents=True,
                exist_ok=True,
            )
            path.write_bytes(original)


def commit_and_push() -> None:
    paths = list(TARGETS)

    try:
        paths.append(
            str(
                Path(__file__)
                .resolve()
                .relative_to(ROOT)
            )
        )
    except ValueError:
        pass

    run(["git", "add", "--", *paths])

    if subprocess.run(
        ["git", "diff", "--cached", "--quiet"],
        cwd=ROOT,
    ).returncode == 0:
        print(
            "The relaxed-frequency research workflow "
            "is already committed."
        )
        return

    run([
        "git",
        "commit",
        "-m",
        (
            "Add relaxed swing-frequency "
            "research control"
        ),
    ])

    branch = subprocess.check_output(
        ["git", "branch", "--show-current"],
        cwd=ROOT,
        text=True,
    ).strip()

    if not branch:
        raise RuntimeError(
            "Cannot push from detached Git state."
        )

    run(["git", "push", "origin", branch])


def main() -> int:
    print("=" * 78)
    print(
        "QPX BOT — RELAXED SWING-FREQUENCY "
        "RESEARCH INSTALLER V13"
    )
    print("=" * 78)
    print(f"Project: {ROOT}")
    ensure_safe()

    try:
        install_files()
        run([
            sys.executable,
            "-m",
            "tests.test_qpx_bot_relaxed_swing_frequency_control",
        ])
        run([
            sys.executable,
            "-m",
            "tests.test_qpx_bot_swing_only_control",
        ])
        run([
            sys.executable,
            "-m",
            "tests.test_qpx_bot_fixed_window_local",
        ])
        run([
            sys.executable,
            "tests/run_all_tests.py",
        ])
    except Exception:
        restore()
        raise

    commit_and_push()

    print()
    print("=" * 78)
    print("CODE INSTALL/TEST/PUSH: COMPLETE")
    print("=" * 78)
    print(
        "Running relaxed-frequency swing-only "
        "research control from local caches."
    )
    print(
        "No provider key and no aggregate download."
    )
    print(
        "Live/paper default strategy remains unchanged."
    )
    print()

    result = run(
        [
            sys.executable,
            "QPX_RUN_RELAXED_SWING_FREQUENCY_CONTROL_"
            "2024_08_06_TO_2026_07_28.py",
        ],
        check=False,
    )

    if result.returncode != 0:
        print()
        print("=" * 78)
        print("CODE PUSH: COMPLETE")
        print("RELAXED SWING RESEARCH CONTROL: INCOMPLETE")
        print("=" * 78)
        return result.returncode

    print()
    print("=" * 78)
    print(
        "QPX RELAXED SWING-FREQUENCY "
        "RESEARCH WORKFLOW V13: COMPLETE"
    )
    print("=" * 78)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
